// 1. Closure: private state a returned function can read/mutate, nothing else can
function makeCounter() {
  let count = 0;               // captured by reference, not by value
  return function () {
    return ++count;
  };
}

// 2. Debounce: closure + timer id, reset the timer on every call
function debounce(fn, delay) {
  let timeoutId = null;        // must be stored, or you can never cancel it
  return function (...args) {
    clearTimeout(timeoutId);   // cancel the pending call, if any
    timeoutId = setTimeout(() => fn.apply(this, args), delay);
  };
}

// 3. Memoize: closure over a cache, keyed by serialized arguments
function memoize(fn) {
  const cache = new Map();
  return function (...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}

// 4. Promise time limit: race the real work against a timeout
function timeLimit(fn, t) {
  return async function (...args) {
    const timeout = new Promise((_, reject) =>
      setTimeout(() => reject('Time Limit Exceeded'), t)
    );
    return Promise.race([fn(...args), timeout]);
  };
}

// 5. Generator: lazy, pausable sequence
function* fibonacci() {
  let [a, b] = [0, 1];
  while (true) {
    yield a;
    [a, b] = [b, a + b];      // execution pauses here between .next() calls
  }
}
